// fakeClock is the injected clock: tests advance it instead of sleeping.
type fakeClock struct {
	t time.Time
}

func (c *fakeClock) Now() time.Time          { return c.t }
func (c *fakeClock) Advance(d time.Duration) { c.t = c.t.Add(d) }

// newTestService wires a Service over a fresh temp-db store with a fake
// clock starting at 2026-10-23T12:00:00Z. Returns the service and the clock.
func newTestService(t *testing.T) (*Service, *fakeClock) {
	t.Helper()
	st, err := store.Open(context.Background(), filepath.Join(t.TempDir(), "pairing.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = st.Close() })
	clock := &fakeClock{t: time.Date(2026, 10, 23, 12, 0, 0, 0, time.UTC)}
	return NewService(st, clock.Now), clock
}

// pair is the test shorthand: one minted request from the given ip.
func pair(t *testing.T, s *Service, ip string) Pairing {
	t.Helper()
	req, err := s.CreateRequest(context.Background(), ip)
	if err != nil {
		t.Fatalf("CreateRequest: %v", err)
	}
	return req
}

// TestServiceCreateRequest covers the mint (INV1/D4): an 8-char code drawn
// only from the unambiguous alphabet, a 128-bit hex pairing id, pending
// status, exactly a 5-minute TTL — and the D7 per-IP fixed-window rate limit
// (excess 429s; the window resets when the clock passes it).
func TestServiceCreateRequest(t *testing.T) {
	ctx := context.Background()
	s, _ := newTestService(t)

	t.Run("mint", func(t *testing.T) {
		req := pair(t, s, "tv")
		if len(req.Code) != codeLen {
			t.Fatalf("code len = %d, want %d", len(req.Code), codeLen)
		}
		for _, r := range req.Code {
			if !strings.ContainsRune(codeAlphabet, r) {
				t.Fatalf("code %q has glyph %q outside the unambiguous alphabet", req.Code, r)
			}
		}
		if len(req.ID) != 2*pairingIDBytes {
			t.Fatalf("pairing id len = %d, want %d hex chars (128-bit)", len(req.ID), 2*pairingIDBytes)
		}
		if req.Status != statusPending {
			t.Fatalf("status = %q, want pending", req.Status)
		}
		if req.ExpiresAt.Sub(req.CreatedAt) != requestTTL {
			t.Fatalf("TTL = %v, want %v", req.ExpiresAt.Sub(req.CreatedAt), requestTTL)
		}
	})

	t.Run("mint_is_unique", func(t *testing.T) {
		a := pair(t, s, "tv")
		b := pair(t, s, "tv")
		if a.ID == b.ID || a.Code == b.Code {
			t.Fatalf("two mints collide: ids %s/%s codes %s/%s", a.ID, b.ID, a.Code, b.Code)
		}
	})

	t.Run("rate_limit_per_ip", func(t *testing.T) {
		fresh, _ := newTestService(t)
		for i := 0; i < rateLimitMax; i++ {
			if _, err := fresh.CreateRequest(ctx, "spammy"); err != nil {
				t.Fatalf("CreateRequest #%d: %v", i+1, err)
			}
		}
		if _, err := fresh.CreateRequest(ctx, "spammy"); !errors.Is(err, ErrRateLimited) {
			t.Fatalf("request #%d err = %v, want ErrRateLimited", rateLimitMax+1, err)
		}
		// A different IP is never throttled by another's window.
		if _, err := fresh.CreateRequest(ctx, "other"); err != nil {
			t.Fatalf("CreateRequest other ip: %v", err)
		}
	})

	// Window reset (D7): advancing past rateWindow re-arms the same IP.
	t.Run("window_resets", func(t *testing.T) {
		limited, clock := newTestService(t)
		for i := 0; i < rateLimitMax; i++ {
			if _, err := limited.CreateRequest(ctx, "tv"); err != nil {
				t.Fatalf("CreateRequest #%d: %v", i+1, err)
			}
		}
		clock.Advance(rateWindow + time.Second)
		if _, err := limited.CreateRequest(ctx, "tv"); err != nil {
			t.Fatalf("CreateRequest after window: %v", err)
		}
	})
}

// TestServiceApproveWait covers the happy path end to end: pending poll →
// approve → the ONE token pickup (INV2) → consumed forever, with the token
// verifiable by hash lookup and the device listed with its approval code.
func TestServiceApproveWait(t *testing.T) {
	ctx := context.Background()
	s, _ := newTestService(t)
	req := pair(t, s, "tv")

	if got, err := s.Wait(ctx, req.ID); err != nil {
		t.Fatalf("Wait before approve: %v", err)
	} else if got.Status != statusPending || got.Token != "" {
		t.Fatalf("pending wait = %+v, want pending/no token", got)
	}

	if got, err := s.Approve(ctx, req.ID); err != nil {
		t.Fatalf("Approve: %v", err)
	} else if got.Status != statusApproved {
		t.Fatalf("approve status = %q, want approved", got.Status)
	}

	var raw string
	if got, err := s.Wait(ctx, req.ID); err != nil {
		t.Fatalf("Wait pickup: %v", err)
	} else if got.Status != statusApproved || got.Token == "" {
		t.Fatalf("pickup = %+v, want approved with a token", got)
	} else {
		raw = got.Token
	}

	// The pickup is single-use: the second poll reports consumed, no token.
	if got, err := s.Wait(ctx, req.ID); err != nil {
		t.Fatalf("Wait after pickup: %v", err)
	} else if got.Status != statusConsumed || got.Token != "" {
		t.Fatalf("second poll = %+v, want consumed/no token (single use)", got)
	}

	// The raw token authenticates (hash lookup) and the device is listed.
	if ok, err := s.LookupToken(ctx, raw); err != nil || !ok {
		t.Fatalf("LookupToken(raw) = %v, %v; want true, nil", ok, err)
	}
	devices, err := s.Devices(ctx)
	if err != nil {
		t.Fatalf("Devices: %v", err)
	}
	if len(devices) != 1 || devices[0].Code != req.Code {
		t.Fatalf("Devices = %+v, want 1 device with approval code %s", devices, req.Code)
	}

	// A pending poll on an unknown id is ErrUnknownPairing (404).
	if _, err := s.Wait(ctx, "no-such-id"); !errors.Is(err, ErrUnknownPairing) {
		t.Fatalf("Wait unknown = %v, want ErrUnknownPairing", err)
	}
}

// TestServiceDenyAndExpiry covers both dead ends: denial is terminal and
// conflicts on re-deny; approval past the TTL is refused with the request
// flipped to expired on the lazy read (INV4), and the pending list drops it.
func TestServiceDenyAndExpiry(t *testing.T) {
	ctx := context.Background()
	s, clock := newTestService(t)

	t.Run("deny_is_terminal", func(t *testing.T) {
		req := pair(t, s, "tv")
		if err := s.Deny(ctx, req.ID); err != nil {
			t.Fatalf("Deny: %v", err)
		}
		if got, err := s.Wait(ctx, req.ID); err != nil {
			t.Fatalf("Wait denied: %v", err)
		} else if got.Status != statusDenied || got.Token != "" {
			t.Fatalf("denied wait = %+v, want denied/no token", got)
		}
		if err := s.Deny(ctx, req.ID); !errors.Is(err, ErrConflict) {
			t.Fatalf("re-Deny = %v, want ErrConflict", err)
		}
		if _, err := s.Approve(ctx, req.ID); !errors.Is(err, ErrConflict) {
			t.Fatalf("Approve denied = %v, want ErrConflict", err)
		}
	})

	t.Run("expired_refuses_approval", func(t *testing.T) {
		req := pair(t, s, "tv")
		clock.Advance(requestTTL + time.Second)
		if _, err := s.Approve(ctx, req.ID); !errors.Is(err, ErrConflict) {
			t.Fatalf("Approve expired = %v, want ErrConflict", err)
		}
		if got, err := s.Wait(ctx, req.ID); err != nil {
			t.Fatalf("Wait expired: %v", err)
		} else if got.Status != statusExpired || got.Token != "" {
			t.Fatalf("expired wait = %+v, want expired/no token", got)
		}
		pending, err := s.ListPending(ctx)
		if err != nil {
			t.Fatalf("ListPending: %v", err)
		}
		for _, p := range pending {
			if p.ID == req.ID {
				t.Fatalf("expired request %s still listed pending", req.ID)
			}
		}
	})

	t.Run("unknown_ids", func(t *testing.T) {
		if _, err := s.Approve(ctx, "no-such-id"); !errors.Is(err, ErrUnknownPairing) {
			t.Fatalf("Approve unknown = %v, want ErrUnknownPairing", err)
		}
		if err := s.Deny(ctx, "no-such-id"); !errors.Is(err, ErrUnknownPairing) {
			t.Fatalf("Deny unknown = %v, want ErrUnknownPairing", err)
		}
	})
}

// TestServiceListPendingDropsShelfExpired covers the stale-list fix: a
// request that aged past its TTL WITHOUT any poll flipping it (status still
// stored 'pending' — the zombie row) is dropped from the pending list, while
// a genuinely still-live request stays listed. The admin panel must never
// offer a dead pairing for approval — approving one 409s/strands the device
// that minted the live code.
func TestServiceListPendingDropsShelfExpired(t *testing.T) {
	ctx := context.Background()
	s, clock := newTestService(t)

	stale := pair(t, s, "tv-a") // minted first, ages out unpolled

	clock.Advance(requestTTL - time.Minute)
	live := pair(t, s, "tv-b")
	clock.Advance(2 * time.Minute) // stale is 1 min past its TTL; live has 4 min left

	pending, err := s.ListPending(ctx)
	if err != nil {
		t.Fatalf("ListPending: %v", err)
	}
	if len(pending) != 1 || pending[0].ID != live.ID {
		t.Fatalf("ListPending = %+v, want only the live request %s (stale %s dropped)", pending, live.ID, stale.ID)
	}
}

// TestServiceLookupToken covers the middleware branch: the picked-up raw
// token resolves, garbage and empty never do, and a miss is (false, nil) —
// never an error.
func TestServiceLookupToken(t *testing.T) {
	ctx := context.Background()
	s, _ := newTestService(t)
	req := pair(t, s, "tv")
	if _, err := s.Approve(ctx, req.ID); err != nil {
		t.Fatalf("Approve: %v", err)
	}
	got, err := s.Wait(ctx, req.ID)
	if err != nil || got.Token == "" {
		t.Fatalf("Wait pickup = %+v, %v; want a token", got, err)
	}

	if ok, err := s.LookupToken(ctx, got.Token); err != nil || !ok {
		t.Fatalf("LookupToken(raw) = %v, %v; want true, nil", ok, err)
	}
	for _, bad := range []string{"garbage", "", got.Token + "x"} {
		if ok, err := s.LookupToken(ctx, bad); err != nil || ok {
			t.Fatalf("LookupToken(%q) = %v, %v; want false, nil", bad, ok, err)
		}
	}
}

// TestServiceRevoke covers revocation: the device disappears from the list,
// its token stops authenticating immediately, and a second revoke is
// ErrUnknownPairing (the handler's 404).
func TestServiceRevoke(t *testing.T) {
	ctx := context.Background()
	s, _ := newTestService(t)
	req := pair(t, s, "tv")
	if _, err := s.Approve(ctx, req.ID); err != nil {
		t.Fatalf("Approve: %v", err)
	}
	got, err := s.Wait(ctx, req.ID)
	if err != nil || got.Token == "" {
		t.Fatalf("Wait pickup = %+v, %v; want a token", got, err)
	}
	devices, err := s.Devices(ctx)
	if err != nil || len(devices) != 1 {
		t.Fatalf("Devices = %+v, %v; want 1", devices, err)
	}
	deviceID := devices[0].ID

	if err := s.Revoke(ctx, deviceID); err != nil {
		t.Fatalf("Revoke: %v", err)
	}
	if ok, err := s.LookupToken(ctx, got.Token); err != nil || ok {
		t.Fatalf("LookupToken after revoke = %v, %v; want false, nil", ok, err)
	}
	empty, err := s.Devices(ctx)
	if err != nil || len(empty) != 0 {
		t.Fatalf("Devices after revoke = %+v, %v; want none", empty, err)
	}
	if err := s.Revoke(ctx, deviceID); !errors.Is(err, ErrUnknownPairing) {
		t.Fatalf("re-Revoke = %v, want ErrUnknownPairing", err)
	}
}
